INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20101, 'Ezekiel 30:12', 'Ezekiel', 30, 12, '&nbsp;زۀ به دريائے نيل اوچ کړم او هغه زمکه به په بدعملو خلقو خرڅه کړم. د غېرو خلقو په لاس به دا زمکه او په دې کښې هر څۀ شاړ کړم. ما مالِک خُدائ دا وفرمائيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20102, 'Ezekiel 30:13', 'Ezekiel', 30, 13, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى، زۀ به بُتان تباه کړم او په ميمفِس کښې مجسمې به ختمې کړم. نور به په مِصر کښې شهزاده نۀ وى، او زۀ به په ټول مُلک دهشت خور کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20103, 'Ezekiel 30:14', 'Ezekiel', 30, 14, '&nbsp;زۀ به بره مِصر تباه کړم، او ضُعن ته به اور ولګوم، او تيبس ته به سزا ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20104, 'Ezekiel 30:15', 'Ezekiel', 30, 15, '&nbsp;زۀ به خپل غضب د مِصر په مضبوط ښار پلوسيوم نازل کړم. او د تيبس ګڼ خلق به تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20105, 'Ezekiel 30:16', 'Ezekiel', 30, 16, '&nbsp;زۀ به په مِصر اور ولګوم او پلوسيوم به د درد نه تاويږى. تيبس به په مينځ نيم کړم، او ميمفِس به په مسلسله پرېشانۍ کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20106, 'Ezekiel 30:17', 'Ezekiel', 30, 17, '&nbsp;د هليوپوليس او بوبستيس ځوانان به په تُوره مړۀ شى، او دا ښارونه به په خپله قبضه کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20107, 'Ezekiel 30:18', 'Ezekiel', 30, 18, '&nbsp;په تحفنحيس کښې به د ورځې تيارۀ شى کله چې زۀ د مِصر جغ مات کړم او د هغۀ زور به ختم شى. هغه به په وريځو کښې پټ شى، او د هغۀ کلى به قبضه کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20108, 'Ezekiel 30:19', 'Ezekiel', 30, 19, '&nbsp;نو زۀ به په مِصر سزا نازله کړم، او هغوئ به پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20109, 'Ezekiel 30:20', 'Ezekiel', 30, 20, '&nbsp;په يوولسم کال د وړومبۍ مياشتې په اوومه ورځ د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20110, 'Ezekiel 30:21', 'Ezekiel', 30, 21, '&nbsp;”اے بنى آدمه، ما د مِصر د بادشاه فِرعون لاس مات کړو. هغه د رغېدلو دپاره ونۀ تړلے شو او نۀ ورسره تخته ولګولے شوه چې هغه دومره مضبوط شى چې تُوره ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20111, 'Ezekiel 30:22', 'Ezekiel', 30, 22, '&nbsp;په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى، زۀ د مِصر د بادشاه فِرعون په خلاف يم. زۀ به د هغۀ دواړه لاسونه مات کړم، روغ او مات دواړه لاسونه به يې مات کړم، او تُوره به د هغۀ د لاس نه وغورزوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20112, 'Ezekiel 30:23', 'Ezekiel', 30, 23, '&nbsp;زۀ به مِصريان په نورو قومونو او مُلکونو کښې خوارۀ وارۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20113, 'Ezekiel 30:24', 'Ezekiel', 30, 24, '&nbsp;زۀ به د بابل د بادشاه لاسونه مضبوط کړم او خپله تُوره به د هغۀ په لاس کښې کېږدم، خو زۀ به د فِرعون لاسونه مات کړم، او هغه به د هغۀ په وړاندې د مرګونى انسان په شان زبيرګى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20114, 'Ezekiel 30:25', 'Ezekiel', 30, 25, '&nbsp;زۀ به د بابل د بادشاه لاسونه مضبوط کړم، خو د فِرعون لاسونه به شل ګوډ کړم. نو بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ يم، کله چې زۀ خپله تُوره د بابل د بادشاه په لاس کښې کېږدم او چې هغه يې د مِصر خلاف راوکاږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20115, 'Ezekiel 30:26', 'Ezekiel', 30, 26, '&nbsp;زۀ به مِصريان د نورو قومونو او مُلکونو په مينځ کښې خوارۀ وارۀ کړم. نو بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20116, 'Ezekiel 31:1', 'Ezekiel', 31, 1, '&nbsp;د جلاوطنۍ په يوولسم کال، د درېمې مياشتې په اوله ورځ د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20117, 'Ezekiel 31:2', 'Ezekiel', 31, 2, '&nbsp;”اے بنى آدمه، د مِصر بادشاه فِرعون او د هغۀ ټولو ګڼو خلقو ته داسې ووايه، په لويئ کښې تۀ خپل ځان چا سره برابر ګڼې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20118, 'Ezekiel 31:3', 'Ezekiel', 31, 3, '&nbsp;تاسو د تکړه اسور په شان يئ، کوم چې يو وخت د لبنان د دِيار د ونې په شان وو، چې څانګې يې ښائسته وې او په ټول ځنګل يې سورے خور وو، او لوړوالے يې وريځو ته رسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20119, 'Ezekiel 31:4', 'Ezekiel', 31, 4, '&nbsp;هغه اوبو غټ کړو، او په زمکه کښې لاندې چينو هغه لوړ کړے وو، او د هغوئ نِهرونه د هغه ونې ګېرچاپېره بهېدل، او د اوبو لختى يې د پټى ټولو ونو ته ورغلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20120, 'Ezekiel 31:5', 'Ezekiel', 31, 5, '&nbsp;نو دا د پټى د نورو ټولو ونو نه ډېره اوچتېدله، او د دې څانګې ډيرې پلنې اوږدې شوې وې ځکه چې جرړو ته زياتې اوبۀ رسېدلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20121, 'Ezekiel 31:6', 'Ezekiel', 31, 6, '&nbsp;د هوا ټولو مارغانو د دې په څانګو کښې جالې جوړې کړې، او ټولو ځنګلى ځناورو د هغې د څانګو لاندې بچى راوړل، او د دُنيا ټول لوئ قومونه د هغې د سورې لاندې کښېناستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20122, 'Ezekiel 31:7', 'Ezekiel', 31, 7, '&nbsp;د خپل اوچتوالى او ګڼو څانګو په وجه هغه ډېره زياته سيرابه وه، ځکه چې جرړو ته يې زياتې اوبۀ رسېدلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20123, 'Ezekiel 31:8', 'Ezekiel', 31, 8, '&nbsp;د خُدائ پاک په باغ کښې د دِيار نورې ونې هغې ته نۀ شوې رسېدلے. د نختر ونو د هغې د څانګو د ګڼوالى مقابله نۀ شوه کولے، او د چنار ونو يې په څانګو کښې برابروالے نۀ شو کولے. د خُدائ پاک په باغ کښې بله يوه ونه هم دومره ښکلې نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20124, 'Ezekiel 31:9', 'Ezekiel', 31, 9, '&nbsp;ما هغه په ګڼو څانګو ښکلې کړې وه، د خُدائ پاک په باغِ عدن کښې ټولو ونو ورسره سيالى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20125, 'Ezekiel 31:10', 'Ezekiel', 31, 10, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، هغه دومره اوچته شوې ده، او سر يې بره وريځو سره لګيږى، او هغه خپل لوړوالى ته مغروره شوې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20126, 'Ezekiel 31:11', 'Ezekiel', 31, 11, '&nbsp;نو ځکه ما هغه د غېرو مُلکونو بادشاهانو ته حواله کړه چې د هغې د ګناهونو په مطابق ورسره رفتار وکړى. ما هغه يوې خوا ته وغورزوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20127, 'Ezekiel 31:12', 'Ezekiel', 31, 12, '&nbsp;او د ټولو نه بې‌رحمه غېر مُلکيانو هغه پرې کړه او داسې يې پرېښودله. د هغې څانګې په غرونو او درو، ګړنګونو کښې راوغورزېدلې، او د هغې څانګې د هغه مُلک په درو کښې ماتې شوې پرېوتې. او د زمکې ټول قومونه د هغې د سورى نه بهر راووتل او هغه يې پرېښوده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20128, 'Ezekiel 31:13', 'Ezekiel', 31, 13, '&nbsp;د هوا ټولو مارغانو په دې غورزېدلې ونه کښې جالې جوړې کړې او د زمکې ځناور يې په څانګو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20129, 'Ezekiel 31:14', 'Ezekiel', 31, 14, '&nbsp;پس د دې نه دې د بل يو مُلک ونه هم په خپله دومره کبر نۀ کوى اګر چې سر يې د وريځو نه اوچت شوے هم وى او جرړې يې اوبو ته رسېدلې دى، ځکه چې هغه ټولې د مرګ خوا ته روانې دى، يعنې د فانى انسانانو سره لاندې قبر ته، د هغوئ سره څوک چې لاندې قبر ته روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20130, 'Ezekiel 31:15', 'Ezekiel', 31, 15, '&nbsp;نو مالِک قادر مطلق خُدائ داسې فرمائى چې، په کومه ورځ چې هغه ونه لاندې قبر ته ښکته شى نو هغه د اوبو چينې به ورباندې ماتم او وير وکړى. ما د هغې نِهرونه بند کړل، او د هغې بې‌حسابه اوبو بهېدل بند شول. نو د دې په وجه ما لبنان ته د ماتم کپړې واغوستې، او د زمکې ټولې ونې وچې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20131, 'Ezekiel 31:16', 'Ezekiel', 31, 16, '&nbsp;ما د هغې د راپرېوتو په آواز دُنيا په لړزان کړه کله چې هغه ما د هغوئ سره لاندې د مړو دُنيا ته ښکته کړه څوک چې قبر ته روان وُو. بيا د عدن ټولې ونې او د لبنان ټولې غوره شوې ونې، او هغه ټولې ونې چې ښې سيرابه شوې وې، هغه لاندې زمکې ته ولېږلے شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20132, 'Ezekiel 31:17', 'Ezekiel', 31, 17, '&nbsp;د هغوئ د نورو مُلکونو اِتحاديان هغه څوک چې د دې په سورى کښې اوسېدل هم د هغوئ سره قبر ته لاړل څوک چې په تُوره قتل شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20133, 'Ezekiel 31:18', 'Ezekiel', 31, 18, '&nbsp;د باغِ عدن کومه يوه ونه تا سره په شان او شوکت کښې مقابله کولے شى؟ خو تۀ به هم د عدن د نورو ونو سره لاندې زمکې ته راوغورزولے شې، تۀ به د ناسنتو په مينځ کښې څملې، د هغوئ سره څوک چې په تُوره وژلے شوى دى. دا به د فِرعون او د هغۀ د ټولو ګڼو خلقو اَنجام وى، ما مالِک خُدائ دا وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20134, 'Ezekiel 32:1', 'Ezekiel', 32, 1, '&nbsp;د دولسم کال، د دولسمې مياشتې په وړومبۍ ورځ، د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20135, 'Ezekiel 32:2', 'Ezekiel', 32, 2, '&nbsp;”اے بنى آدمه، د مِصر د بادشاه فِرعون په حقله د غم مرثيه ووايه او هغۀ ته ووايه، تۀ د مُلکونو په مينځ کښې لکه د زمرى په شان وې، خو په حقيقت کښې تۀ لکه د سمندر د اژدها په شان يې چې په خپلو نِهرونو کښې ګرځې راګرځې او په خپلو پښو سره اوبۀ تاووې او نِهرونه خړوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20136, 'Ezekiel 32:3', 'Ezekiel', 32, 3, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به ډېر خلق درولېږم چې تا زما په جال کښې راګېر کړى، او په هغې کښې به دې د اوبو نه رابهر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20137, 'Ezekiel 32:4', 'Ezekiel', 32, 4, '&nbsp;زۀ به تا په زمکه راوغورزوم او په اوچ مېدان به دې راوولم. زۀ به د هوا ټول مارغان پرېږدم چې په تا کښېنى او د زمکې ټول ځناور به په تا باندې خپل ځانونه ماړۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20138, 'Ezekiel 32:5', 'Ezekiel', 32, 5, '&nbsp;زۀ به ستا غوښه په غرونو ونولم او ستا په لاش به دَرې ډکې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20139, 'Ezekiel 32:6', 'Ezekiel', 32, 6, '&nbsp;زۀ به زمکه دومره ستا په وينو رنګ کړم چې د غرونو سر ته ورسى، او ګړنګونه به ستا د وينو ډک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20140, 'Ezekiel 32:7', 'Ezekiel', 32, 7, '&nbsp;کله چې زۀ ستا د ژوند شمع مړه کړم، نو زۀ به آسمان پټ کړم او د دې ستورى به تور کړم، زۀ به نمر په وريځو سره پټ کړم، او سپوږمۍ به خپله رڼا نۀ خوروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20141, 'Ezekiel 32:8', 'Ezekiel', 32, 8, '&nbsp;زۀ به ستا دپاره د آسمان ټولې رڼاګانې تيارې کړم، زۀ به ستا په زمکه باندې تيارۀ راولم. مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20142, 'Ezekiel 32:9', 'Ezekiel', 32, 9, '&nbsp;زۀ به د ډېرو قومونو زړونه پرېشانه کړم کله چې زۀ د نورو مُلکونو په مينځ کښې تا تباه کړم، په هغه مُلکونو کښې چې تا نۀ پېژندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20143, 'Ezekiel 32:10', 'Ezekiel', 32, 10, '&nbsp;زۀ به ډېر خلق ستا د حالاتو په وجه پرېشانه کړم، او ستا په وجه به د هغوئ بادشاهان د يرې نه ولړزيږى کله چې زۀ خپله تُوره د هغوئ په وړاندې ښکاره کړم. ستا د غورزېدو په ورځ به هغوئ ټول هره لحظه د خپل ژوند دپاره لړزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20144, 'Ezekiel 32:11', 'Ezekiel', 32, 11, '&nbsp;ځکه مالِک قادر مطلق خُدائ داسې فرمائى چې، د بابل د بادشاه تُوره به ستاسو خلاف راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20145, 'Ezekiel 32:12', 'Ezekiel', 32, 12, '&nbsp;زۀ به ستا لښکر ختم کړم د هغه طاقتورو خلقو په تُورو چې د ټولې دُنيا بې‌رحمه خلق دى. هغوئ به د مِصر دبدبه ختمه کړى او د هغې ټولې لښکرې به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20146, 'Ezekiel 32:13', 'Ezekiel', 32, 13, '&nbsp;زۀ به د هغې ټول څاروى چې د سيند په خوا کښې څريږى تباه کړم، نور به د انسان پښې دا اوبۀ نۀ تاووى او نۀ به د ځناورو پښې دا خړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20147, 'Ezekiel 32:14', 'Ezekiel', 32, 14, '&nbsp;بيا به زۀ د دې اوبۀ دومره خاموشه کړم او د دې دريابونه به لکه د تېلو په شان بهيږى، مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20148, 'Ezekiel 32:15', 'Ezekiel', 32, 15, '&nbsp;کله چې زۀ د مِصر مُلک وران ويجاړ کړم او دا زمکه د هر څۀ نه خالى کړم، کله چې زۀ هغوئ ټول هلاک کړم څوک چې هلته اوسيږى، نو بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20149, 'Ezekiel 32:16', 'Ezekiel', 32, 16, '&nbsp;دا هغه د غم مرثيه ده چې دوئ به يې هغۀ ته ووائى. د دې مُلک لوڼه به دا وائى، د مِصر او د هغوئ ګڼ خلقو دپاره به د غم مرثيه وائى، مالِک قادر مطلق خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20150, 'Ezekiel 32:17', 'Ezekiel', 32, 17, '&nbsp;د دولسم کال د اولې مياشتې په پينځلسمه ورځ د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20151, 'Ezekiel 32:18', 'Ezekiel', 32, 18, '&nbsp;”اے بنى آدمه، د مِصر په لښکرو باندې وير وکړه او هغه دواړه د نورو تکړه قومونو لوريانو سره لاندې زمکې ته حواله کړه، د هغوئ سره څوک چې قبر ته روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20152, 'Ezekiel 32:19', 'Ezekiel', 32, 19, '&nbsp;هغوئ ته ووايه، ولې تۀ د نورو نه ډېره ښائسته يې څۀ؟ ‎‏عالمِ ارواح ته لاړه شه او د ناسنتو په مينځ کښې پرېوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20153, 'Ezekiel 32:20', 'Ezekiel', 32, 20, '&nbsp;هغوئ به د هغه چا سره ‎مړۀ شى څوک چې په تُوره قتل شوى دى. تُوره راويستلے شوې ده، هغه پرېږده چې خپل ټول لښکر سره عالمِ ارواح ته راښکلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20154, 'Ezekiel 32:21', 'Ezekiel', 32, 21, '&nbsp;لاندې قبر نه به تکړه مشران د مِصر او د هغۀ د اِتحاديانو په حقله وائى، هغوئ لاندې راغلل او هغوئ د ناسنتو سره مړۀ پراتۀ دى، هغوئ سره چې په تُوره مړۀ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20155, 'Ezekiel 32:22', 'Ezekiel', 32, 22, '&nbsp;اسور خپل ټول فوج سره هلته ‎پروت دے، هغه د خپلو ټولو وژلے شوو د قبرونو په مينځ کښې راګېر دے، هغوئ ټولو سره چې په تُوره قتل شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20156, 'Ezekiel 32:23', 'Ezekiel', 32, 23, '&nbsp;د هغوئ قبرونه په ژوره کنده کښې دى او د هغۀ فوجيان د هغۀ د قبر نه چاپېره ښخ دى. هغوئ ټولو چا چې د ژوندو په دُنيا کښې دهشت خورولو هغوئ قتل شول، او په تُوره مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20157, 'Ezekiel 32:24', 'Ezekiel', 32, 24, '&nbsp;عيلام هم هلته دے د هغۀ ټولې لښکرې د هغۀ د قبر نه چاپېره پرتې دى، هغوئ ټول حلال کړے شوى، په تُوره وژلے شوى دى. هغوئ ټولو چا چې د دُنيا په ټولو خلقو کښې دهشت خورولو لاندې زمکې ته ناسنته ښکته شول. هغوئ خپله بې‌عزتى د هغوئ سره وزغمى څوک چې لاندې عالمِ ارواح ته روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20158, 'Ezekiel 32:25', 'Ezekiel', 32, 25, '&nbsp;د هغۀ دپاره د مړو په مينځ کښې د آرام ځائ جوړ شو، د هغې ټولو فوجيانو سره د هغې د قبر نه چاپېره. هغوئ ټول ناسنته دى او په تُوره وژلے شوى دى. ځکه چې هغوئ د دُنيا په ټولو خلقو کښې خپل دهشت خور کړے وو، هغوئ د هغه چا سره شرمنده پراتۀ دى څوک چې په قبر کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20159, 'Ezekiel 32:26', 'Ezekiel', 32, 26, '&nbsp;مسک او توبل هلته سره د خپلو ټولو لښکرو د هغوئ د قبرونو نه چاپېره دى. هغوئ ټول ناسنته دى، په تُوره وژلے شوى دى ځکه چې هغوئ د دُنيا په ټولو خلقو کښې خپل دهشت خور کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20160, 'Ezekiel 32:27', 'Ezekiel', 32, 27, '&nbsp;هغوئ د خپلو نورو جنګيالو په شان په عزت ښخ نۀ شول، څوک چې د خپلو وسلو سره عالمِ ارواح ته ښکته شوى وُو او چې ډالونه يې په لاشونو پراتۀ وُو او تُورې يې د سرونو د لاندې اېښې وې. د هغوئ ګناه د هغوئ دپاسه وه ځکه کله چې هغوئ لا ژوندى وُو نو هغوئ په هر چا دهشت خور کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20161, 'Ezekiel 32:28', 'Ezekiel', 32, 28, '&nbsp;تۀ به هم، اے فِرعونه تيکه تيکه شې او د ناسنته په مينځ کښې به ښخ کړے شې، د هغوئ سره چې په تُوره مړۀ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20162, 'Ezekiel 32:29', 'Ezekiel', 32, 29, '&nbsp;ادوم هلته د خپلو بادشاهانو او شهزادګانو سره دے، باوجود د خپل ټول طاقت هغوئ د هغوئ په مينځ کښې پراتۀ دى څوک چې په تُوره وژلے شوى دى. هغوئ د ناسنتو سره پراتۀ دى، د هغوئ سره څوک چې لاندې کندې ته روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20163, 'Ezekiel 32:30', 'Ezekiel', 32, 30, '&nbsp;د شمال ټول شهزادګان او ټول صيدانيان هلته پراتۀ دى، هغوئ لاندې د وژلے شوو سره په بې‌عزتۍ لاړل باوجود د دې چې د هغوئ د طاقت په وجه دهشت خور وو. او اوس د هغوئ لاشونه د ناسنته په حالت کښې د مړو سره پراتۀ دى. او هغوئ خپله بې‌عزتى د هغوئ سره وزغمى څوک چې لاندې قبر ته روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20164, 'Ezekiel 32:31', 'Ezekiel', 32, 31, '&nbsp;فِرعون او د هغۀ ټول فوجيان به هغوئ وګورى او هغه به د خپل ټول لښکر دپاره تسلى ومومى څوک چې په تُوره مړۀ کړے شوى وُو، مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20165, 'Ezekiel 32:32', 'Ezekiel', 32, 32, '&nbsp;تر دې چې ما هغه پرېښے وو چې هغوئ د دُنيا په ټولو خلقو کښې خپل دهشت خور کړى، فِرعون او د هغۀ ټول فوجيان به د ناسنتو په مينځ کښې پراتۀ وى، د هغوئ سره چې په تُوره وژلے شوى دى، مالِک قادر مطلق خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20166, 'Ezekiel 33:1', 'Ezekiel', 33, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20167, 'Ezekiel 33:2', 'Ezekiel', 33, 2, '&nbsp;”اے بنى آدمه د خپلو خلقو سره خبرې وکړه او هغوئ ته ووايه، کله چې زۀ د يو مُلک خلاف جنګ شروع کړم، نو د هغه مُلک خلق د خپلو خلقو نه يو سړے غوره کړى چې د هغوئ محافظ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20168, 'Ezekiel 33:3', 'Ezekiel', 33, 3, '&nbsp;کۀ محافظ وګورى چې دشمن د هغه مُلک خلاف راروان دے نو هغه به بيګل وغږوى چې خلقو له خبردارے ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20169, 'Ezekiel 33:4', 'Ezekiel', 33, 4, '&nbsp;نو بيا چې څوک د بيګل آواز واورى او هغې ته توجو ورنۀ کړى او جنګ او تُوره راشى او د هغۀ ژوند ختم کړى نو خون به يې په خپله غاړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20170, 'Ezekiel 33:5', 'Ezekiel', 33, 5, '&nbsp;ځکه چې هغۀ د کله نه چې د بيګل آواز واورېدو او توجو يې ورنۀ کړه، نو خون يې په خپله غاړه دے. کۀ چرې هغۀ خبردارى ته توجو ورکړې وه، نو هغۀ به خپل ځان بچ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20171, 'Ezekiel 33:6', 'Ezekiel', 33, 6, '&nbsp;خو کۀ محافظ دشمن وګورى چې راروان دے او بيګل ونۀ غږوى چې خلقو له خبردارے ورکړى او دشمن راشى او کۀ د يو سړى ژوند ختم کړى، نو هغه سړے خو به د خپلې ګناه په وجه مړ شى، خو زۀ به محافظ د هغۀ د مرګ ذمه وار وګرځوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20172, 'Ezekiel 33:7', 'Ezekiel', 33, 7, '&nbsp;اے بنى آدمه، ما تۀ د بنى اِسرائيلو د قوم دپاره محافظ جوړ کړې، نو بيا هغه خبرې واوره کومې چې زۀ تا ته کوم نو زما د خوا نه تۀ هغوئ ته خبردارے ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20173, 'Ezekiel 33:8', 'Ezekiel', 33, 8, '&nbsp;کله چې زۀ يو بدعمله ته ووايم، ”اے بدعمله، تۀ به په حقيقت کښې مړ شې،“ او تۀ د هغوئ سره خبرې ونۀ کړې چې هغوئ د خپلو عملونو نه واوړى، نو هغه بدعمله به د خپلو ګناهونو په وجه مړ شى، او زۀ به تا د هغۀ د مرګ ذمه وار کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20174, 'Ezekiel 33:9', 'Ezekiel', 33, 9, '&nbsp;خو کۀ تۀ يو بدعمله سړى له خبردارے ورکړې چې خپلې غلطې طريقې پرېږدى او هغه داسې ونۀ کړى، هغه به د خپلو ګناهونو په وجه مړ شى، خو تا خپل ځان د هغۀ د خون د ذمه وارۍ نه بچ کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20175, 'Ezekiel 33:10', 'Ezekiel', 33, 10, '&nbsp;”اے بنى آدمه، د بنى اِسرائيلو قوم ته ووايه، تاسو داسې وايئ چې، زمونږ جرمونو او ګناهونو مونږ لاندې کړى يُو، او مونږ د هغوئ په وجه سخا او تباه شوى يُو، نو مونږ به څنګه ژوندى پاتې شُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20176, 'Ezekiel 33:11', 'Ezekiel', 33, 11, '&nbsp;هغوئ ته ووايه چې، زما دې په خپل ذات قسم وى، مالِک قادر مطلق خُدائ داسې فرمائى، زۀ د بدعمله په مرګ هيڅ نۀ خوشحالېږم، بلکې په دې خوشحالېږم چې هغه ټول غلط کارونه پرېږدى او ژوندے پاتې شى. راوګرځئ، د خپلو بدو لارو نه راوګرځئ. اے بنى اِسرائيلو، نو بيا ولې تاسو مړۀ کېدل غواړئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20177, 'Ezekiel 33:12', 'Ezekiel', 33, 12, '&nbsp;اے بنى آدمه، خپل د مُلک خلقو ته ووايه، د صادق انسان صداقت به هغه بچ نۀ کړى کۀ هغه نافرمانى کوى، او د بدعمله انسان بدعملى به هغه د مرګ کندې ته ونۀ غورزوى کۀ هغه دا پرېږدى. کۀ چرې يو صادق سړے ګناهونه وکړى، نو هغه به د خپل پخوانى صداقت په وجه بچ نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20178, 'Ezekiel 33:13', 'Ezekiel', 33, 13, '&nbsp;کۀ چرې زۀ يو صادق انسان ته ووايم چې تۀ به يقيناً ژوندے پاتې شې، خو هغه بيا په خپل صداقت اعتماد وکړى او بد کارونه شروع کړى، نو زۀ به د دۀ يو ښۀ عمل هم ياد نۀ کړم، کوم چې هغۀ پخوا کړى دى، هغه به د هغه بدو کارونو په وجه چې کوم هغۀ کړى دى، مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20179, 'Ezekiel 33:14', 'Ezekiel', 33, 14, '&nbsp;او فرض کړئ کۀ چرې زۀ يو بدعمله ته ووايم چې تۀ به يقيناً مړ شې، نو کېدے شى چې هغه په دې اورېدو سره د خپلو ګناهونو نه توبه وکړى او هغه کارونه شروع کړى کوم چې د اِنصاف او صحيح دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20180, 'Ezekiel 33:15', 'Ezekiel', 33, 15, '&nbsp;لکه مثال په طور هغه خپل ضمانت واپس کړى کوم چې هغۀ د خلقو نه اخستے وى، او هر هغه څۀ واپس کړى کوم چې هغۀ پټ کړى وى، او زما په ژوند ورکونکى شريعت عمل وکړى او نور د بدۍ نه مخ واړوى، نو يقيناً هغه به ژوندے پاتې شى، مړ به نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20181, 'Ezekiel 33:16', 'Ezekiel', 33, 16, '&nbsp;يوه ګناه به هم کومه چې هغۀ کړى وى د هغۀ خلاف نۀ حسابيږى. ځکه چې هغۀ هغه څۀ وکړل څۀ چې ښۀ او نېک دى، هغه به يقيناً ژوندے پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20182, 'Ezekiel 33:17', 'Ezekiel', 33, 17, '&nbsp;خو بيا هم ستا د مُلک خلق وائى چې، د مالِک خُدائ طريقې بې‌اِنصافه دى. خو دا هم دوئ دى چې د هغوئ طريقې بې‌اِنصافه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20183, 'Ezekiel 33:18', 'Ezekiel', 33, 18, '&nbsp;کۀ يو صادق انسان خپل صداقت پرېږدى او بدعملى شروع کړى، هغه به د دې کار په وجه مړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20184, 'Ezekiel 33:19', 'Ezekiel', 33, 19, '&nbsp;او کۀ چرې يو بدکاره د خپلې بدکارۍ نه واوړى او هغه څۀ وکړى چې کوم نېک او صحيح دى، نو په داسې کولو سره به هغه خپل ژوند بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20185, 'Ezekiel 33:20', 'Ezekiel', 33, 20, '&nbsp;خو اے د اِسرائيل قومه، تاسو وايئ چې، د مالِک خُدائ طريقې د اِنصاف نۀ دى. خو زۀ به ستاسو د هر يو عدالت ستاسو د عملونو او طريقو په مطابق وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20186, 'Ezekiel 33:21', 'Ezekiel', 33, 21, '&nbsp;زمونږ د جلاوطنۍ په دولسم کال، د لسمې مياشتې په پينځمه ورځ، يو سړے څوک چې د يروشلم نه راتښتېدلے وو ما له راغلو او وې وئيل، ”هغه ښار راوغورزېدلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20187, 'Ezekiel 33:22', 'Ezekiel', 33, 22, '&nbsp;د هغه کس د راتلو نه يو ماښام وړاندې، د مالِک خُدائ لاس په ما باندې وو، هغۀ زما خولۀ په سحر کښې د هغه سړى د راتلو نه وړاندې پرانستله. نو بيا زما خولۀ پرانستلے شوې وه او زۀ نور چپ نۀ شوم پاتې کېدے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20188, 'Ezekiel 33:23', 'Ezekiel', 33, 23, '&nbsp;نو بيا د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20189, 'Ezekiel 33:24', 'Ezekiel', 33, 24, '&nbsp;”اے بنى آدمه، کوم خلق چې د بنى اِسرائيلو په مُلک کښې په دې شاړو او کنډراتو کښې اوسيږى نو هغوئ وائى چې، اِبراهيم صرف يو سړے وو، خو بيا هم هغۀ دا زمکه حاصله کړه. بلکې مونږ ډېر يُو، په يقين سره مونږ ته دا زمکه لکه زمونږ د خپل ملکيت په شان راکړے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20190, 'Ezekiel 33:25', 'Ezekiel', 33, 25, '&nbsp;نو دې خلقو ته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى چې، تاسو د وينو نه ډکې غوښې خورئ، او د معبودانو عبادت کوئ، او وينه تويوئ، نو تاسو په داسې کولو سره خپل ځان د دې زمکې حقدار ګڼئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20191, 'Ezekiel 33:26', 'Ezekiel', 33, 26, '&nbsp;اے قاتلانو، بُت پرستانو، حرام کارو، آيا تاسو د دې زمکې د وراثت قابل يئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20192, 'Ezekiel 33:27', 'Ezekiel', 33, 27, '&nbsp;نو هغوئ ته دا ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى، زما دې په خپل ذات قسم وى، هغه څوک چې په دې کنډراتو کښې پاتې کيږى هغوئ به په تُوره مړۀ شى، او څوک چې په دشتو او ميرو کښې بهر اوسيږى هغوئ به ځناورو ته حواله کړم چې وې خورى، او څوک چې په قلعه ګانو او غارونو کښې دى په وبا به مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20193, 'Ezekiel 33:28', 'Ezekiel', 33, 28, '&nbsp;زۀ به د دې مُلک نه صحرا او بيابان جوړ کړم، او د هغۀ مغرورانه طاقت به ختم کړم، او د بنى اِسرائيلو غرونه به په شاړو بدل کړم چې هيڅ څوک هم په هغې تېرېدے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20194, 'Ezekiel 33:29', 'Ezekiel', 33, 29, '&nbsp;د هغوئ د حرامو کارونو په وجه چې کوم هغوئ کړى دى زۀ به دا مُلک په صحرا بدلوم نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20195, 'Ezekiel 33:30', 'Ezekiel', 33, 30, '&nbsp;مالِک خُدائ وفرمائيل چې، ”اے بنى آدمه، ترڅو چې ستا خبره ده، ستا د مُلک خلق د خپلو کورونو د دېوالونو خوا کښې او په دروازو کښې ودريږى او ستا په حقله يو بل ته وائى، راځئ چې د هغۀ پېغام واورو کوم چې هغۀ ته د مالِک خُدائ نه مِلاو شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20196, 'Ezekiel 33:31', 'Ezekiel', 33, 31, '&nbsp;زما خلق به تا له راشى، لکه څنګه چې هغوئ همېشه راځى، او ستا په وړاندې به کښېنى چې ستا خبرو ته غوږ ونيسى، خو هغوئ په دې عمل نۀ کوى. په خپله خولۀ هغوئ د عېش عشرت خبرې کوى، او زړونه يې هم د لالچ نه ډک دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20197, 'Ezekiel 33:32', 'Ezekiel', 33, 32, '&nbsp;په حقيقت کښې تۀ د هغوئ دپاره د يو داسې موسيقار په شان يې چې په خوږ آواز سره د مينې سندرې وائى او يا ښۀ ساز غږوى. نو هم داسې هغوئ ستا خبرې اورى خو عمل پرې نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20198, 'Ezekiel 33:33', 'Ezekiel', 33, 33, '&nbsp;هرکله چې دا هر څۀ رښتيا شى، او يقيناً داسې به وشى، نو بيا به هغوئ په دې باندې پوهه شى چې يو نبى د هغوئ په مينځ کښې اوسېدو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20199, 'Ezekiel 34:1', 'Ezekiel', 34, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20200, 'Ezekiel 34:2', 'Ezekiel', 34, 2, '&nbsp;”اے بنى آدمه، د شپونکو يعنې د بنى اِسرائيلو د مشرانو خلاف پېشګوئې وکړه، او هغوئ ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، د بنى اِسرائيلو په شپونکو دې افسوس وى څوک چې صرف خپله ګېډه څروى. ولې يو شپون ته پکار نۀ دى چې خپله رمه وڅروى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');